import React, { useEffect, useState } from "react";
import axios from "axios";
import { LogOut } from "lucide-react";

const API_BASE_URL = "http://localhost:9091";

function AdminDashboard({ token, onLogout }) {
  const [medicines, setMedicines] = useState([]);

  useEffect(() => {
    axios
      .get(`${API_BASE_URL}/api/admin/medicines`, {
        headers: { Authorization: `Bearer ${token}` },
      })
      .then((res) => setMedicines(res.data))
      .catch((err) => {
        console.error("Admin fetch failed:", err);
        setMedicines([
          { id: 1, name: "Mock Admin Item", price: 99.99, stockQuantity: 5 },
        ]);
      });
  }, [token]);

  return (
    <div className="p-6 max-w-4xl mx-auto">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-indigo-700">Admin Dashboard</h2>
        <button
          onClick={onLogout}
          className="text-red-500 hover:text-red-700 flex items-center text-sm"
        >
          <LogOut className="w-4 h-4 mr-1" />
          Logout
        </button>
      </div>
      <div className="bg-white p-4 rounded-lg shadow">
        <h3 className="text-lg font-semibold mb-2">Inventory List</h3>
        <ul className="space-y-1">
          {medicines.map((med) => (
            <li key={med.id} className="flex justify-between p-2 bg-gray-50 rounded">
              <span>{med.name}</span>
              <span className="font-medium">
                ₹{med.price?.toFixed(2) || "N/A"} (Stock: {med.stockQuantity})
              </span>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

export default AdminDashboard;
